(function(){'use strict';const c=POD_CATALOG,e=POD_ENGINE,$=id=>document.getElementById(id);let category='',family=null;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const node=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;};
for(const p of c.providers){const option=node('option',p.name);option.value=p.id;$('provider').append(option);const box=node('div'),a=node('a',p.name);a.href=p.homepage;a.target='_blank';a.rel='noopener noreferrer';box.append(a,node('small',c.products.some(x=>x.providerId===p.id)?'Kaynaklı kayıtlar var':'Katalog henüz eklenmedi'));$('providerList').append(box);}
function nav(){$('categories').replaceChildren();for(const cat of [{id:'',label:'Tüm kategoriler'},...c.categories]){const b=node('button',cat.label,cat.id===category?'active':'');b.type='button';b.setAttribute('aria-pressed',String(cat.id===category));b.addEventListener('click',()=>{category=cat.id;family=null;location.hash='';nav();render();});$('categories').append(b);}}
function render(){$('listing').hidden=false;$('detail').hidden=true;const max=$('maxPrice').value,groups=e.groups(c,{query:$('query').value,category,provider:$('provider').value,material:$('material').value,maxPrice:max===''?null:Number(max),sort:$('sort').value});$('heading').textContent=c.categories.find(x=>x.id===category)?.label||'Ürünleri keşfet';$('coverage').textContent=c.products.length+' kayıt · '+new Set(c.products.map(p=>p.providerId)).size+' üretici · '+c.categories.length+' ana kategori';$('resultCount').textContent=groups.length+' ürün grubu bulundu';$('cards').replaceChildren();if(!groups.length){$('cards').append(node('div','Bu arama veya kategoride henüz ürün kaydı yok. Filtreleri temizleyebilir ya da başka kategori seçebilirsin.','empty'));return;}
for(const group of groups){const def=c.families.find(x=>x.id===group.family),card=node('article',undefined,'card');card.append(node('span',c.categories.find(x=>x.id===group.offers[0].category).label,'category-label'),node('h2',def.label),node('p',def.description,'card-description'),node('p',group.providerCount+' üretici · '+group.offers.length+' katalog kaydı'),node('p',money(group.minPrice),'price'),node('small','başlangıç ürün fiyatı; kargo hariç'));const b=node('button','Fiyatları karşılaştır');b.addEventListener('click',()=>{location.hash='product='+encodeURIComponent(group.family);});card.append(b);$('cards').append(card);}}
function detail(){const def=c.families.find(x=>x.id===family);if(!def){family=null;render();return;}$('listing').hidden=true;$('detail').hidden=false;$('detailTitle').textContent=def.label;$('breadcrumb').textContent=c.categories.find(x=>x.id===def.category).label;$('detailNote').textContent=def.description;$('offers').replaceChildren();for(const p of e.sort(c.products.filter(x=>x.family===family).map(x=>e.quote(x,$('country').value)),$('offerSort').value)){const tr=node('tr'),td=text=>{const el=node('td',text);tr.append(el);return el;};td(c.providers.find(x=>x.id===p.providerId).name).append(node('small',p.title));td().append(node('strong',money(p.baseMinor)),node('small',p.priceBasis));td((p.material||'Materyal doğrulanmadı')+' · '+p.sizes);td(p.shippingMinor==null?(p.shippingFrom?.[$('country').value]!=null?money(p.shippingFrom[$('country').value])+' başlangıç; kesin değil':'Adres / varyant gerekli'):money(p.shippingMinor));td(p.totalMinor==null?'Hesaplanamadı':money(p.totalMinor));td((p.production||'Üretim bilinmiyor')+' / '+(p.deliveryDays==null?'Teslimat bilinmiyor':p.deliveryDays+' gün'));const link=node('a','Üreticiye git');link.href=p.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';td().append(link);$('offers').append(tr);}}
function route(){const hash=location.hash.slice(1);if(hash.startsWith('product=')){try{family=decodeURIComponent(hash.slice(8));}catch{family=null;}detail();}else{family=null;render();}}
$('searchForm').addEventListener('submit',ev=>{ev.preventDefault();family=null;location.hash='';render();});$('query').addEventListener('input',()=>{family=null;if(location.hash.startsWith('#product='))location.hash='';render();});for(const id of ['provider','material','maxPrice','sort'])$(id).addEventListener('change',render);for(const id of ['country','offerSort'])$(id).addEventListener('change',detail);$('back').addEventListener('click',()=>{location.hash='';render();});$('reset').addEventListener('click',()=>{category='';for(const id of ['query','provider','material','maxPrice'])$(id).value='';$('sort').value='base';nav();render();});window.addEventListener('hashchange',route);nav();route();})();
